        },
        {
          "find": "    for epoch in range(1, NUM_EPOCHS + 1):\n        model.train()\n        total_loss = 0.0",
          "replace": "    for epoch in range(1, NUM_EPOCHS + 1):\n        if epoch <= 10:\n            lr_scale = epoch / 10.0\n        else:\n            progress = (epoch - 10) / 190.0\n            lr_scale = 0.1 + 0.9 * 0.5 * (1.0 + math.cos(math.pi * progress))\n        for param_group in optimizer.param_groups:\n            param_group[\"lr\"] = LR * lr_scale\n        model.train()\n        total_loss = 0.0"
        }
      ]
    }
  ],
  "change_summary": "Add 10-epoch linear learning-rate warmup followed by cosine decay to 0.1× LR at epoch 200; enforce the 200-epoch cap. Model architecture and predictor remain unchanged."
